public class SuppliersTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.function.Supplier<java.util.List<String>> s = Suppliers.emptyListSupplier();
        check("emptyListSupplier() is not null", true, s != null);
        try {
            java.util.List<String> a = s.get();
            java.util.List<String> b = s.get();
            check("get() yields an empty list", "[]", String.valueOf(a));
            check("two calls yield distinct list objects", true, a != b);
            a.add("changed");
            check("later calls are still empty", "[]", String.valueOf(s.get()));
        } catch (RuntimeException e) {
            System.out.println("FAIL  supplier usage -- threw " + e.getClass().getSimpleName());
            failures += 3;
        }

        check("orDefault uses the supplied value", "hello", Suppliers.orDefault(() -> "hello", "backup"));
        check("orDefault falls back on null", "backup", Suppliers.orDefault(() -> null, "backup"));
        check("orDefault works for Integer too", 7, Suppliers.orDefault(() -> null, 7));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

