public class Suppliers {

    public static java.util.function.Supplier<java.util.List<String>> emptyListSupplier() {
        return () -> new java.util.ArrayList<>();
    }

    public static <T> T orDefault(java.util.function.Supplier<T> s, T fallback) {
        T value = s.get();
        if (value == null) {
            return fallback;
        }
        return value;
    }
}
